import React, { useState, useEffect } from "react";
import "./Dashboard.css";
import { getTasks, createTask, updateTask, deleteTask } from "../../api/taskService";
import { getEvents, createEvent, updateEvent, deleteEvent } from "../../api/eventService";

function Dashboard({ onLogout }) {
  const [tasks, setTasks] = useState([]);
  const [events, setEvents] = useState([]);

  // Load tasks/events
  useEffect(() => {
    async function fetchData() {
      try {
        setTasks(await getTasks());
        setEvents(await getEvents());
      } catch (err) {
        console.error("Error fetching data:", err.message);
      }
    }
    fetchData();

    // Request notification permission
    if (Notification.permission !== "granted") {
      Notification.requestPermission();
    }
  }, []);

  // Reminder check
  useEffect(() => {
    const interval = setInterval(() => {
      tasks.forEach(task => {
        if (task.time) {
          const taskTime = new Date(task.time).getTime();
          const now = Date.now();
          if (taskTime - now < 60000 && !task.notified) {
            new Notification("Nityo Reminder", { body: `Task "${task.name}" is due soon!` });
            task.notified = true;
          }
        }
      });
    }, 30000);
    return () => clearInterval(interval);
  }, [tasks]);

  // Productivity score
  const totalTasks = tasks.length;
  const completedTasks = tasks.filter(t => t.status === "Completed").length;
  const productivityScore = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

  return (
    <div className="dashboard-container">
      {/* Header with Logout */}
      <div className="dashboard-header">
        <h1 className="dashboard-title">Nityo Dashboard</h1>
        <button className="logout-btn" onClick={onLogout}>Logout</button>
      </div>

      {/* Tasks */}
      <div className="dashboard-card">
        <div className="emoji">✏️</div>
        <h3>Tasks</h3>
        {/* Add Task Form */}
        {/* Use createTask, updateTask, deleteTask here */}
      </div>

      {/* Reports */}
      <div className="dashboard-card">
        <div className="emoji">📊</div>
        <h3>Reports</h3>
        <p>Total Tasks: {totalTasks}</p>
        <p>Completed: {completedTasks}</p>
        <p>Productivity Score: {productivityScore}%</p>
        <div className="progress-bar">
          <div className="progress-fill" style={{ width: `${productivityScore}%` }}></div>
        </div>
      </div>

      {/* Events */}
      <div className="dashboard-card">
        <div className="emoji">📅</div>
        <h3>Events</h3>
        {/* Add Event Form */}
        {/* Use createEvent, updateEvent, deleteEvent here */}
      </div>

      {/* Instructions */}
      <div className="dashboard-card">
        <div className="emoji">📖</div>
        <h3>Instructions</h3>
        <ul>
          <li>Add tasks with name, description, and time.</li>
          <li>Track workflow (Pending / In‑Progress / Completed).</li>
          <li>Manage events with date and time.</li>
          <li>Get reminders and notifications before deadlines.</li>
          <li>View productivity reports with progress bar.</li>
          <li>Logout anytime from Dashboard top bar.</li>
        </ul>
      </div>

      {/* Theme Toggle */}
      <div className="dashboard-card">
        <div className="emoji">🌙☀️</div>
        <button className="action-btn" onClick={() => document.body.classList.toggle("dark-mode")}>
          Toggle Theme
        </button>
      </div>
    </div>
  );
}

export default Dashboard;
